pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 amount, uint256 smaller) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        smaller = bound(smaller, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(smaller < amount);
        vm.assume(address(this).balance >= amount);
        bool reverted1;
        try c.go{value: amount}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        bool reverted2;
        try c.go{value: smaller}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assertTrue(reverted1 || !reverted2);
    }

    function testFuzz_run(uint256 amount, uint256 smaller) public {
        _run(amount, smaller);
    }

    receive() external payable {}
}
